using BmsDesktop.Infrastructure;
using Npgsql;
namespace BmsDesktop.Finance;
public sealed class ExpeditionService { private readonly Database _db; public ExpeditionService(Database db)=>_db=db; public async Task FundAsync(Guid tripId,decimal amount,string description){if(amount<=0)throw new ArgumentException("Dana jalan harus lebih dari nol.");await using var cn=await _db.OpenAsync();await using var tx=await cn.BeginTransactionAsync();await using(var c=new NpgsqlCommand("insert into expedition_costs(id,trip_id,cost_type,description,amount) values(@id,@t,'ROAD_CASH',@d,@a)",cn,tx)){c.Parameters.AddWithValue("id",Guid.NewGuid());c.Parameters.AddWithValue("t",tripId);c.Parameters.AddWithValue("d",description);c.Parameters.AddWithValue("a",amount);await c.ExecuteNonQueryAsync();}await using(var u=new NpgsqlCommand("update expedition_trips set status='FINANCE_FUNDED' where id=@id and status='DRAFT'",cn,tx)){u.Parameters.AddWithValue("id",tripId);if(await u.ExecuteNonQueryAsync()!=1)throw new InvalidOperationException("Trip tidak dalam status DRAFT.");}await tx.CommitAsync();} public async Task CompleteLogisticsAsync(Guid tripId){await using var cn=await _db.OpenAsync();await using var c=new NpgsqlCommand("update expedition_trips set status='LOGISTICS_COMPLETED' where id=@id and status='FINANCE_FUNDED'",cn);c.Parameters.AddWithValue("id",tripId);if(await c.ExecuteNonQueryAsync()!=1)throw new InvalidOperationException("Trip belum didanai Finance atau sudah diproses.");} }
